    """Dispatch a recovered job in the current thread.

    Called from a daemon thread spawned during startup recovery.
    _run_job_in_background is defined later in this module, so we
    import it lazily.
    """
    # Small delay to let the app finish booting
    import time
    time.sleep(2)
    try:
        _run_job_in_background_fn = globals().get("_run_job_in_background")
        if _run_job_in_background_fn:
            _run_job_in_background_fn(job_id)
        else:
            logger.error(f"Recovery dispatch: _run_job_in_background not found for job {job_id}")
    except Exception as e:
        logger.error(f"Recovery dispatch failed for job {job_id}: {e}", exc_info=True)


